ALTER TABLE photo.billing_operation_items ADD COLUMN success_contract text NOT NULL DEFAULT 'v2_adopted_outputs_v1'
 CHECK(success_contract IN('v2_adopted_outputs_v1','restoration_selected_v1','open_eyes_selected_v1','relight_selected_v1','local_portrait_selected_v1'));
-- +goose StatementBegin
CREATE FUNCTION photo.billing_selected_contract(p_operation text,p_version text) RETURNS text
LANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT CASE WHEN p_version<>'1' THEN NULL WHEN p_operation IN('portrait.glare','image.reflection') THEN 'restoration_selected_v1'
 WHEN p_operation='portrait.open_eyes' THEN 'open_eyes_selected_v1' WHEN p_operation='image.relight' THEN 'relight_selected_v1'
 WHEN p_operation IN('portrait.hair','portrait.clothing') THEN 'local_portrait_selected_v1' END;
$$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE FUNCTION photo.billing_operation_session(p_tenant uuid,p_run uuid) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
 SELECT nullif(CASE WHEN config_snapshot ? 'v28_restoration' THEN config_snapshot->'v28_restoration'->>'auth_session_id'
 WHEN config_snapshot ? 'v28_open_eyes' THEN config_snapshot->'v28_open_eyes'->>'auth_session_id'
 WHEN config_snapshot ? 'v28_relight' THEN config_snapshot->'v28_relight'->>'auth_session_id'
 WHEN config_snapshot ? 'v28_local_portrait' THEN config_snapshot->'v28_local_portrait'->>'auth_session_id'
 ELSE coalesce(config_snapshot->>'auth_session_id',config_snapshot->'v27_semantic'->>'auth_session_id') END,'')::uuid FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run;
$$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE FUNCTION photo.billing_selected_source(p_tenant uuid,p_run uuid,p_task uuid) RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE;op text;wire text;source uuid;
BEGIN
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run;
 SELECT operation INTO op FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run AND id=p_task;
 IF op IN('portrait.glare','image.reflection') THEN
  source:=coalesce((r.config_snapshot->'v28_restoration'->>'base_asset_version_id')::uuid,(r.v28_restoration_descriptor_jcs::jsonb->'params'->'base'->>'asset_version_id')::uuid);
 ELSIF op='portrait.open_eyes' THEN
  source:=coalesce((r.config_snapshot->'v28_open_eyes'->>'base_asset_version_id')::uuid,(r.v28_donor_descriptor_jcs::jsonb->'params'->'base'->>'asset_version_id')::uuid);
 ELSIF op='image.relight' THEN
  wire:=r.v28_relight_intent->>'params_jcs';source:=(wire::jsonb->'base'->>'asset_version_id')::uuid;
 ELSIF op IN('portrait.hair','portrait.clothing') THEN
  wire:=r.config_snapshot->'v28_local_portrait'->'intent'->>'params_jcs';source:=(wire::jsonb->'base'->>'asset_version_id')::uuid;
 END IF;
 RETURN source;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE FUNCTION photo.billing_selected_outcome(p_tenant uuid,p_run uuid,p_task uuid,p_contract text)
RETURNS TABLE(route text,image_id uuid,image_sha text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE;t photo.tasks%ROWTYPE;v photo.reviews%ROWTYPE;old_tenant text;session uuid;selected record;
BEGIN
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run AND id=p_task;
 IF p_contract IS DISTINCT FROM photo.billing_selected_contract(t.operation,t.operation_version) THEN RETURN;END IF;
 session:=photo.billing_operation_session(p_tenant,p_run);
 old_tenant:=current_setting('app.tenant_id',true);PERFORM set_config('app.tenant_id',p_tenant::text,true);
 IF p_contract='local_portrait_selected_v1' AND EXISTS(SELECT 1 FROM photo.task_results WHERE tenant_id=p_tenant AND id=t.canonical_result_id AND NOT review_required) THEN
  RETURN QUERY SELECT 'candidate'::text,a.candidate_id,a.candidate_sha FROM photo.v2_workflows w
   CROSS JOIN LATERAL photo.get_v28_local_portrait_result(p_tenant,r.created_by,session,w.id) a
   WHERE w.tenant_id=p_tenant AND w.run_id=p_run AND a.result_id=t.canonical_result_id AND a.operation=t.operation;
 ELSE
  SELECT * INTO v FROM photo.reviews WHERE tenant_id=p_tenant AND run_id=p_run AND task_id=p_task AND kind=t.operation AND state='decided' AND revision=2;
  IF FOUND THEN
   IF p_contract='restoration_selected_v1' AND photo.v28_restoration_review_completion_ready(p_tenant,p_task) AND (t.operation<>'portrait.glare' OR photo.v28_glare_completed_source_ready(p_tenant,p_task,t.canonical_result_id)) THEN
    RETURN QUERY SELECT s.route,s.image_id,s.image_sha FROM photo.get_v28_restoration_review_selection(p_tenant,r.created_by,session,v.id) s;
   ELSIF p_contract='open_eyes_selected_v1' AND photo.v28_open_eyes_review_completion_ready(p_tenant,p_task) AND photo.v28_open_eyes_selected_authority(p_tenant,v.id,r.created_by,session) THEN
    RETURN QUERY SELECT s.route,s.image_id,s.image_sha FROM photo.get_v28_open_eyes_review_selection(p_tenant,r.created_by,session,v.id) s;
   ELSIF p_contract='relight_selected_v1' AND photo.v28_relight_review_completion_ready(p_tenant,p_task) THEN
    RETURN QUERY SELECT s.route,s.image_id,s.image_sha FROM photo.get_v28_relight_review_selection(p_tenant,r.created_by,session,v.id) s;
   ELSIF p_contract='local_portrait_selected_v1' THEN
    RETURN QUERY SELECT s.route,s.image_id,s.image_sha FROM photo.get_v28_local_portrait_review_selection(p_tenant,r.created_by,session,v.id) s;
   END IF;
  END IF;
 END IF;
 PERFORM set_config('app.tenant_id',coalesce(old_tenant,''),true);
END $$;
-- +goose StatementEnd
-- Discover children only from native typed ownership, never from a client parent.
-- +goose StatementBegin
CREATE FUNCTION photo.billing_link_selected_children(p_tenant uuid,p_root uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE req uuid;child record;
BEGIN
 SELECT id INTO req FROM photo.billing_operation_requests WHERE tenant_id=p_tenant AND run_id=p_root AND state='accepted';IF NOT FOUND THEN RETURN;END IF;
 FOR child IN SELECT DISTINCT c.id FROM photo.runs c JOIN photo.tasks t ON t.tenant_id=c.tenant_id AND t.run_id=p_root
 JOIN photo.runs parent ON parent.tenant_id=t.tenant_id AND parent.id=t.run_id AND parent.created_by=c.created_by
 WHERE c.tenant_id=p_tenant AND c.kind='preview' AND (c.v26_derivative_task_id=t.id OR c.v28_restoration_preview_task_id=t.id)
 AND c.config_snapshot->>'source_result_id'=t.canonical_result_id::text AND photo.billing_selected_contract(t.operation,t.operation_version) IS NOT NULL LOOP
  IF EXISTS(SELECT 1 FROM photo.billing_operation_requests WHERE tenant_id=p_tenant AND run_id=child.id) THEN RAISE EXCEPTION 'BILLING_CHILD_ALREADY_CHARGED';END IF;
  INSERT INTO photo.billing_operation_children(tenant_id,request_id,run_id) VALUES(p_tenant,req,child.id) ON CONFLICT DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM photo.billing_operation_children WHERE tenant_id=p_tenant AND request_id=req AND run_id=child.id) THEN RAISE EXCEPTION 'BILLING_CHILD_INVALID';END IF;
 END LOOP;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE FUNCTION photo.billing_link_selected_preview() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE parent uuid;
BEGIN
 IF NEW.v28_restoration_preview_task_id IS NULL AND NEW.v26_derivative_task_id IS NULL THEN RETURN NEW;END IF;
 SELECT run_id INTO parent FROM photo.tasks WHERE tenant_id=NEW.tenant_id AND id=coalesce(NEW.v28_restoration_preview_task_id,NEW.v26_derivative_task_id);
 IF parent IS NOT NULL THEN PERFORM photo.billing_link_selected_children(NEW.tenant_id,parent);END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER billing_selected_preview AFTER INSERT OR UPDATE OF v26_derivative_task_id,v28_restoration_preview_task_id ON photo.runs FOR EACH ROW EXECUTE FUNCTION photo.billing_link_selected_preview();

CREATE TABLE photo.billing_operation_selections(
 tenant_id uuid NOT NULL,item_id uuid NOT NULL,contract text NOT NULL,route text NOT NULL CHECK(route IN('candidate','base','skip')),
 image_id uuid,image_sha text,review_id uuid,decision_hash text,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,item_id),FOREIGN KEY(tenant_id,item_id) REFERENCES photo.billing_operation_items(tenant_id,id),
 FOREIGN KEY(tenant_id,image_id) REFERENCES photo.artifacts(tenant_id,id),FOREIGN KEY(tenant_id,review_id) REFERENCES photo.reviews(tenant_id,id),
 CHECK((route='skip' AND image_id IS NULL AND image_sha IS NULL) OR (route IN('candidate','base') AND image_id IS NOT NULL AND image_sha IS NOT NULL AND image_sha ~ '^[0-9a-f]{64}$')));
ALTER TABLE photo.billing_operation_selections ENABLE ROW LEVEL SECURITY;
ALTER TABLE photo.billing_operation_selections FORCE ROW LEVEL SECURITY;
CREATE POLICY billing_owner ON photo.billing_operation_selections TO photo_fn_owner USING(true) WITH CHECK(true);
REVOKE ALL ON photo.billing_operation_selections FROM PUBLIC,photo_api,photo_scheduler,photo_worker;
GRANT SELECT,INSERT ON photo.billing_operation_selections TO photo_fn_owner;
CREATE TRIGGER billing_operation_selection_immutable BEFORE UPDATE ON photo.billing_operation_selections FOR EACH ROW EXECUTE FUNCTION photo.reject_content_update('tenant_id','item_id','contract','route','image_id','image_sha','review_id','decision_hash','recorded_at');
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.billing_prepare_operations(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo SET lock_timeout='200ms' AS $$
DECLARE r photo.runs%ROWTYPE;project uuid;session uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM photo.billing_operation_controls WHERE tenant_id=p_tenant AND enabled) THEN RETURN false;END IF;
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_AUTHORITY_INVALID';END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run;
 SELECT project_id INTO project FROM photo.v2_workflows WHERE tenant_id=p_tenant AND run_id=p_run;
 IF r.id IS NULL THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
 -- Existing standard roots and their typed technical children keep their own
 -- authority and resources. A client-supplied parent UUID is never an exemption.
 IF EXISTS(SELECT 1 FROM photo.billing_usage_run_links WHERE tenant_id=p_tenant AND run_id=p_run)
 OR EXISTS(SELECT 1 FROM photo.editor_effect_builds WHERE tenant_id=p_tenant AND final_run_id=p_run)
 OR EXISTS(SELECT 1 FROM photo.billing_operation_children c JOIN photo.billing_operation_requests q ON q.tenant_id=c.tenant_id AND q.id=c.request_id AND q.state='accepted' WHERE c.tenant_id=p_tenant AND c.run_id=p_run)
 OR r.config_snapshot ? 'v26_render' THEN RETURN false;END IF;
 IF project IS NULL THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
 session:=photo.billing_operation_session(p_tenant,p_run);
 IF NOT photo.v2_editor_authorized(p_tenant,project,r.created_by,session) THEN RAISE EXCEPTION 'BILLING_AUTHORITY_INVALID';END IF;
 RETURN true;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.billing_bind_operations(p_tenant uuid,p_run uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE;req photo.billing_operation_requests%ROWTYPE;pol photo.billing_operation_policies%ROWTYPE;
 task record;res record;period uuid;rid uuid;lid uuid;fence uuid;claim uuid;generation bigint;hash bytea;context text;q bigint;available numeric;instance text;source_version uuid;original_sha text;selected_source uuid;expected_contract text;
BEGIN
 IF NOT photo.billing_prepare_operations(p_tenant,p_run) THEN RETURN NULL;END IF;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR UPDATE;
 SELECT sha256(convert_to(r.config_hash||coalesce(string_agg(t.id::text||'/'||t.operation||'/'||t.operation_version||'/'||t.input_digest,',' ORDER BY t.id),''),'UTF8')) INTO hash FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run;
 SELECT * INTO req FROM photo.billing_operation_requests WHERE tenant_id=p_tenant AND run_id=p_run FOR UPDATE;
 IF FOUND THEN
  IF req.request_hash<>hash THEN RAISE EXCEPTION 'BILLING_IDEMPOTENCY_CONFLICT';END IF;
  RETURN req.id;
 END IF;
 IF EXISTS(SELECT 1 FROM photo.billing_operation_children WHERE tenant_id=p_tenant AND run_id=p_run) THEN RETURN NULL;END IF;
 IF r.graph_sealed OR r.status<>'draft' OR r.cancel_requested THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
 SELECT id INTO period FROM photo.billing_periods WHERE tenant_id=p_tenant AND state='open' AND starts_at<=clock_timestamp() AND ends_at>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PERIOD_INVALID';END IF;
 SELECT CASE WHEN workflow_type='preview' THEN 'preview' ELSE 'standalone' END INTO context FROM photo.v2_workflows WHERE tenant_id=p_tenant AND run_id=p_run;
 -- Leaf result tasks are the user-visible units; prerequisites are included.
 -- Policy is context-specific: a standard_root policy cannot authorize standalone.
 IF NOT EXISTS(SELECT 1 FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run) THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
 rid:=gen_random_uuid();instance:='operation/'||p_run;
 INSERT INTO photo.billing_operation_requests(id,tenant_id,run_id,period_id,request_hash) VALUES(rid,p_tenant,p_run,period,hash);
 FOR task IN SELECT t.* FROM photo.tasks t WHERE t.tenant_id=p_tenant AND t.run_id=p_run
 AND NOT EXISTS(SELECT 1 FROM photo.task_edges e WHERE e.tenant_id=t.tenant_id AND e.run_id=p_run AND e.prerequisite_id=t.id)
 ORDER BY t.operation,t.operation_version,t.id LOOP
  SELECT * INTO pol FROM photo.billing_operation_policies WHERE operation_code=task.operation AND operation_version=task.operation_version AND charge_context=context AND effective_from<=clock_timestamp() ORDER BY policy_version DESC LIMIT 1;
  IF NOT FOUND OR pol.billing_class NOT IN('paid_operation','free_beta') OR pol.resource_code IS NULL OR pol.resource_code NOT LIKE 'operation.%'
   OR (pol.billing_class='free_beta' AND pol.resource_code NOT LIKE 'operation.beta.%') OR (pol.billing_class='paid_operation' AND pol.resource_code LIKE 'operation.beta.%')
   OR pol.success_contract IS DISTINCT FROM coalesce(photo.billing_selected_contract(task.operation,task.operation_version),'v2_adopted_outputs_v1') OR pol.rerun_policy<>'none' THEN RAISE EXCEPTION 'BILLING_OPERATION_POLICY_REQUIRED';END IF;
  expected_contract:=photo.billing_selected_contract(task.operation,task.operation_version);
  selected_source:=NULL;
  IF expected_contract IS NULL THEN
   IF task.node_key !~ ('^'||replace(task.operation,'.','[.]')||':[0-9]{1,4}$') THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
  ELSE
   selected_source:=photo.billing_selected_source(p_tenant,p_run,task.id);
   IF selected_source IS NULL THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
  END IF;
  SELECT v.id,orig.sha256 INTO source_version,original_sha FROM photo.snapshot_items si
  JOIN photo.asset_versions v ON v.tenant_id=si.tenant_id AND v.id=si.asset_version_id
  JOIN photo.assets a ON a.tenant_id=v.tenant_id AND a.id=v.asset_id AND a.deleted_at IS NULL AND a.upload_state='verified'
  JOIN photo.artifacts orig ON orig.tenant_id=a.tenant_id AND orig.id=a.original_artifact_id AND orig.state='ready' AND orig.verified_at IS NOT NULL AND orig.object_version IS NOT NULL AND orig.object_version NOT IN('','null') AND (orig.expires_at IS NULL OR orig.expires_at>clock_timestamp())
  WHERE si.tenant_id=p_tenant AND si.snapshot_id=r.input_snapshot_id AND (CASE WHEN expected_contract IS NULL THEN si.ordinal=split_part(task.node_key,':',2)::integer ELSE si.asset_version_id=selected_source END) AND si.artifact_id=v.master_artifact_id AND si.sha256=v.content_hash;
  IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_SOURCE_INVALID';END IF;
  q:=CASE WHEN pol.billing_class='free_beta' THEN 1 ELSE pol.units_per_success END;
  IF pol.billing_class='free_beta' AND (SELECT coalesce(sum(i.quantity),0) FROM photo.billing_operation_items i JOIN photo.billing_operation_requests b ON b.tenant_id=i.tenant_id AND b.id=i.request_id WHERE i.tenant_id=p_tenant AND i.policy_id=pol.id AND b.period_id=period AND i.state<>'released')+q>pol.beta_budget THEN RAISE EXCEPTION 'BILLING_BETA_BUDGET_EXCEEDED';END IF;
  INSERT INTO photo.billing_operation_items(tenant_id,request_id,task_id,source_version_id,original_digest,policy_hash,policy_id,resource_code,quantity,claim_id,success_contract)
  VALUES(p_tenant,rid,task.id,source_version,decode(original_sha,'hex'),pol.policy_snapshot_hash,pol.id,pol.resource_code,q,NULL,pol.success_contract);
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM photo.billing_operation_items WHERE tenant_id=p_tenant AND request_id=rid) THEN RAISE EXCEPTION 'BILLING_OPERATION_POLICY_REQUIRED';END IF;
 -- Claims are populated after deterministic resource locking and whole-request
 -- deficit checks. Temporary NULL claims must be funded before the deferred scope check.
 FOR res IN SELECT resource_code,sum(quantity)::bigint AS quantity FROM photo.billing_operation_items WHERE tenant_id=p_tenant AND request_id=rid GROUP BY resource_code ORDER BY resource_code LOOP
  PERFORM photo.billing_quota_lock(p_tenant,res.resource_code);
  SELECT coalesce(sum(remaining_quantity),0) INTO available FROM photo.billing_credit_buckets WHERE tenant_id=p_tenant AND resource_code=res.resource_code AND state='active' AND starts_at<=clock_timestamp() AND (expires_at IS NULL OR expires_at>clock_timestamp());
  IF (SELECT sum(quantity) FROM photo.billing_operation_items WHERE tenant_id=p_tenant AND request_id=rid)>1 AND available<res.quantity THEN RAISE EXCEPTION 'BILLING_QUOTA_EXCEEDED';END IF;
 END LOOP;
 FOR task IN SELECT * FROM photo.billing_operation_items WHERE tenant_id=p_tenant AND request_id=rid ORDER BY resource_code,task_id LOOP
  SELECT id,fence_token INTO lid,fence FROM photo.billing_admission_leases
  WHERE tenant_id=p_tenant AND resource_code=task.resource_code AND period_id=period AND instance_id=instance AND state='active' AND expires_at>clock_timestamp()
   AND allocated_quantity+allowance_quantity-issued_quantity-returned_quantity>=task.quantity ORDER BY photo.billing_admission_leases.generation DESC LIMIT 1;
  IF NOT FOUND THEN
   FOR res IN SELECT id,fence_token FROM photo.billing_admission_leases WHERE tenant_id=p_tenant AND resource_code=task.resource_code AND instance_id=instance AND state='active' ORDER BY id LOOP
    PERFORM photo.billing_close_admission_lease(p_tenant,task.resource_code,res.id,res.fence_token);
   END LOOP;
   SELECT coalesce(max(l.generation),0)+1 INTO generation FROM photo.billing_admission_leases l WHERE l.tenant_id=p_tenant AND l.resource_code=task.resource_code AND l.period_id=period AND l.instance_id=instance;
   IF task.quantity>(SELECT chunk_quantity FROM photo.billing_admission_policies WHERE resource_code=task.resource_code AND policy_version=1) THEN
    lid:=photo.billing_allocate_paid_operation_lease(p_tenant,task.resource_code,period,instance,generation,1,'op/'||task.id,task.quantity);
   ELSE
   lid:=photo.billing_allocate_admission_lease(p_tenant,task.resource_code,period,instance,generation,1,'op/'||task.id);
   END IF;
   SELECT fence_token INTO fence FROM photo.billing_admission_leases WHERE id=lid;
  END IF;
  claim:=photo.billing_issue_funding_claim(p_tenant,task.resource_code,lid,fence,'op/'||task.id,hash,task.quantity);
  UPDATE photo.billing_operation_items SET claim_id=claim WHERE tenant_id=p_tenant AND id=task.id;
 END LOOP;
 -- Reuse chunks across billable units in this admission, then return their
 -- unused capacity. No worker step performs another commercial check.
 FOR res IN SELECT id,resource_code,fence_token FROM photo.billing_admission_leases WHERE tenant_id=p_tenant AND instance_id=instance AND state='active' ORDER BY resource_code,id LOOP
  PERFORM photo.billing_close_admission_lease(p_tenant,res.resource_code,res.id,res.fence_token);
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM photo.v2_workflows w WHERE w.tenant_id=p_tenant AND w.run_id=p_run AND photo.v2_editor_authorized(p_tenant,w.project_id,r.created_by,photo.billing_operation_session(p_tenant,p_run))) THEN RAISE EXCEPTION 'BILLING_AUTHORITY_INVALID';END IF;
 RETURN rid;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.seal_v2_graph(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE funded uuid;
BEGIN
 -- Subtransaction also rolls back tickets/claims when a legacy graph guard
 -- refuses seal. Commercial denial remains an error to the caller.
 BEGIN
  funded:=photo.billing_bind_operations(p_tenant,p_run);
  IF NOT photo.seal_before_operation_billing(p_tenant,p_run) THEN RAISE EXCEPTION 'BILLING_GRAPH_REFUSED';END IF;
  IF funded IS NOT NULL AND NOT EXISTS(SELECT 1 FROM photo.runs r JOIN photo.v2_workflows w ON w.tenant_id=r.tenant_id AND w.run_id=r.id WHERE r.tenant_id=p_tenant AND r.id=p_run AND photo.v2_editor_authorized(p_tenant,w.project_id,r.created_by,photo.billing_operation_session(p_tenant,p_run))) THEN RAISE EXCEPTION 'BILLING_AUTHORITY_INVALID';END IF;
  RETURN true;
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='BILLING_GRAPH_REFUSED' THEN RETURN false;END IF;RAISE;END;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.billing_guard_operation_item() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
BEGIN
 IF (NEW.id,NEW.tenant_id,NEW.request_id,NEW.task_id,NEW.source_version_id,NEW.original_digest,NEW.policy_hash,NEW.policy_id,NEW.resource_code,NEW.quantity,NEW.success_contract)
 IS DISTINCT FROM (OLD.id,OLD.tenant_id,OLD.request_id,OLD.task_id,OLD.source_version_id,OLD.original_digest,OLD.policy_hash,OLD.policy_id,OLD.resource_code,OLD.quantity,OLD.success_contract)
 OR (OLD.claim_id IS NOT NULL AND NEW.claim_id IS DISTINCT FROM OLD.claim_id)
 OR (OLD.state<>'accepted' AND NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'BILLING_OPERATION_ITEM_IMMUTABLE' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.billing_settle_operations(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE req photo.billing_operation_requests%ROWTYPE;r photo.runs%ROWTYPE;item record;t photo.tasks%ROWTYPE;z photo.task_results%ROWTYPE;success boolean;proof bytea;selected jsonb;old_tenant text;
BEGIN
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR UPDATE;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO req FROM photo.billing_operation_requests WHERE tenant_id=p_tenant AND run_id=p_run FOR UPDATE;
 IF NOT FOUND OR req.state<>'accepted' THEN RETURN false;END IF;
 PERFORM photo.billing_link_selected_children(p_tenant,p_run);
 FOR item IN SELECT DISTINCT resource_code FROM photo.billing_operation_items WHERE tenant_id=p_tenant AND request_id=req.id ORDER BY resource_code LOOP PERFORM photo.billing_quota_lock(p_tenant,item.resource_code);END LOOP;
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run FOR SHARE;
 IF r.status NOT IN('completed','completed_with_errors','failed','cancelled') OR EXISTS(SELECT 1 FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run AND state NOT IN('succeeded','failed','cancelled','skipped'))
 OR EXISTS(SELECT 1 FROM photo.billing_operation_children l JOIN photo.runs c ON c.tenant_id=l.tenant_id AND c.id=l.run_id WHERE l.tenant_id=p_tenant AND l.request_id=req.id AND c.status NOT IN('completed','completed_with_errors','failed','cancelled')) OR EXISTS(SELECT 1 FROM photo.billing_operation_children l JOIN photo.tasks c ON c.tenant_id=l.tenant_id AND c.run_id=l.run_id WHERE l.tenant_id=p_tenant AND l.request_id=req.id AND c.state NOT IN('succeeded','failed','cancelled','skipped')) THEN RETURN false;END IF;
 FOR item IN SELECT * FROM photo.billing_operation_items WHERE tenant_id=p_tenant AND request_id=req.id AND state='accepted' ORDER BY resource_code,task_id LOOP
  SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND id=item.task_id FOR SHARE;
  success:=false;
  IF t.state='succeeded' AND NOT t.cancel_requested AND NOT r.cancel_requested AND r.status<>'cancelled' AND (item.success_contract='v2_adopted_outputs_v1' OR r.status<>'failed') THEN
   SELECT * INTO z FROM photo.task_results WHERE tenant_id=p_tenant AND id=t.canonical_result_id AND task_id=t.id AND attempt=t.attempt AND fencing_token=t.fencing_token;
   IF NOT FOUND OR jsonb_typeof(z.outputs)<>'array' OR jsonb_array_length(z.outputs)<>1
   OR NOT EXISTS(SELECT 1 FROM photo.inbox WHERE tenant_id=p_tenant AND consumer='v2-adopt' AND event_id=photo.v2_adoption_event_id(t.id,z.id))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(z.outputs) o LEFT JOIN photo.artifacts a ON a.tenant_id=p_tenant AND a.id::text=o->>'artifact_id' AND a.sha256=o->>'sha256'
    WHERE a.id IS NULL OR a.state<>'ready' OR a.verified_at IS NULL OR a.object_version IS NULL OR a.object_version IN('','null') OR a.expires_at<=clock_timestamp()
    OR a.created_by_task_id IS DISTINCT FROM t.id OR a.produced_attempt IS DISTINCT FROM t.attempt OR a.produced_fence IS DISTINCT FROM t.fencing_token
    OR NOT EXISTS(SELECT 1 FROM photo.v2_artifact_links l JOIN photo.v2_workflows w ON w.tenant_id=l.tenant_id AND w.id=l.workflow_id WHERE w.tenant_id=p_tenant AND w.run_id=p_run AND l.artifact_id=a.id AND l.sha256=a.sha256 AND l.purpose=encode(sha256(convert_to('tasks/'||t.id||'/$','UTF8')),'hex')))
   THEN RAISE EXCEPTION 'BILLING_OPERATION_PROOF_UNAVAILABLE';END IF;
   IF item.success_contract<>'v2_adopted_outputs_v1' THEN
    SELECT jsonb_agg(to_jsonb(s)) INTO selected FROM photo.billing_selected_outcome(p_tenant,p_run,t.id,item.success_contract) s;
    IF jsonb_array_length(selected) IS DISTINCT FROM 1 OR coalesce(selected->0->>'route','') NOT IN('candidate','base','skip') THEN RAISE EXCEPTION 'BILLING_OPERATION_PROOF_UNAVAILABLE';END IF;
    success:=selected->0->>'route'='candidate';
    INSERT INTO photo.billing_operation_selections(tenant_id,item_id,contract,route,image_id,image_sha,review_id,decision_hash)
    SELECT p_tenant,item.id,item.success_contract,selected->0->>'route',(selected->0->>'image_id')::uuid,selected->0->>'image_sha',
     (SELECT id FROM photo.reviews WHERE tenant_id=p_tenant AND task_id=t.id AND state='decided' LIMIT 1),
     (SELECT decision_hash FROM photo.reviews WHERE tenant_id=p_tenant AND task_id=t.id AND state='decided' LIMIT 1);
   ELSE
   IF z.review_required THEN
    IF NOT EXISTS(SELECT 1 FROM photo.reviews WHERE tenant_id=p_tenant AND task_id=t.id AND state='decided' AND decision IN('accept','reject','skip') AND candidate_artifact_id::text=z.outputs->0->>'artifact_id' AND candidate_hash=z.outputs->0->>'sha256') THEN RAISE EXCEPTION 'BILLING_OPERATION_PROOF_UNAVAILABLE';END IF;
    success:=EXISTS(SELECT 1 FROM photo.reviews WHERE tenant_id=p_tenant AND task_id=t.id AND state='decided' AND decision='accept' AND candidate_artifact_id::text=z.outputs->0->>'artifact_id' AND candidate_hash=z.outputs->0->>'sha256');
   ELSE success:=true;END IF;
   END IF;
  END IF;
  proof:=sha256(convert_to(coalesce(selected::text,'generic')||'/'||req.id::text||'/'||item.id||'/'||coalesce(z.id::text,'none')||'/'||success::text,'UTF8'));
  PERFORM photo.billing_finalize_funding_claim(p_tenant,item.resource_code,item.claim_id,CASE WHEN success THEN item.quantity ELSE 0 END,proof);
  UPDATE photo.billing_operation_items SET state=CASE WHEN success THEN 'consumed' ELSE 'released' END,result_id=CASE WHEN success THEN z.id ELSE NULL END,proof_hash=proof WHERE tenant_id=p_tenant AND id=item.id;
  z:=NULL;selected:=NULL;
 END LOOP;
 UPDATE photo.billing_operation_requests SET state='settled' WHERE tenant_id=p_tenant AND id=req.id;
 RETURN true;
END $$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE FUNCTION photo.billing_local_selected_ready(p_tenant uuid,p_run uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r photo.runs%ROWTYPE;t photo.tasks%ROWTYPE;selection record;session uuid;
BEGIN
 SELECT * INTO r FROM photo.runs WHERE tenant_id=p_tenant AND id=p_run;
 IF NOT FOUND OR r.kind<>'v2' OR r.status<>'waiting_review' OR NOT r.graph_sealed OR r.cancel_requested THEN RETURN false;END IF;
 IF (SELECT count(*) FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run)<>1 OR (SELECT count(*) FROM photo.reviews WHERE tenant_id=p_tenant AND run_id=p_run)<>1 THEN RETURN false;END IF;
 SELECT * INTO t FROM photo.tasks WHERE tenant_id=p_tenant AND run_id=p_run;
 IF t.operation NOT IN('portrait.hair','portrait.clothing') OR t.state<>'succeeded' OR t.cancel_requested THEN RETURN false;END IF;
 SELECT * INTO selection FROM photo.billing_selected_outcome(p_tenant,p_run,t.id,'local_portrait_selected_v1');
 IF NOT FOUND THEN RETURN false;END IF;
 IF selection.route<>'candidate' AND (EXISTS(SELECT 1 FROM photo.task_edges WHERE tenant_id=p_tenant AND prerequisite_id=t.id)
 OR EXISTS(SELECT 1 FROM photo.artifacts a JOIN photo.tasks consumer ON consumer.tenant_id=a.tenant_id
  JOIN photo.runs c ON c.tenant_id=consumer.tenant_id AND c.id=consumer.run_id
  WHERE a.tenant_id=p_tenant AND a.created_by_task_id=t.id AND consumer.id<>t.id
  AND NOT coalesce(c.kind='preview' AND c.v26_derivative_task_id=t.id AND c.config_snapshot->>'source_result_id'=t.canonical_result_id::text,false)
  AND (consumer.inputs @> jsonb_build_array(jsonb_build_object('artifact_id',a.id::text,'sha256',a.sha256))
   OR EXISTS(SELECT 1 FROM photo.v2_task_inputs i WHERE i.tenant_id=consumer.tenant_id AND i.task_id=consumer.id AND i.artifact_id=a.id AND i.sha256=a.sha256)))) THEN RETURN false;END IF;
 RETURN NOT EXISTS(SELECT 1 FROM photo.graph_expansions WHERE tenant_id=p_tenant AND run_id=p_run AND state<>'closed');
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE FUNCTION photo.billing_finalize_local_selected() RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE candidate photo.runs%ROWTYPE;current_run photo.runs%ROWTYPE;
 cursor_value bigint;event_id uuid;
BEGIN
 SELECT r.* INTO candidate FROM photo.runs r JOIN photo.reviews v
  ON v.tenant_id=r.tenant_id AND v.run_id=r.id
 WHERE r.kind='v2' AND r.status='waiting_review'
  AND v.kind IN('portrait.hair','portrait.clothing') AND EXISTS(SELECT 1 FROM photo.billing_operation_requests q WHERE q.tenant_id=r.tenant_id AND q.run_id=r.id AND q.state='accepted') AND v.state='decided'
  AND EXISTS(SELECT 1 FROM photo.billing_operation_requests q WHERE q.tenant_id=r.tenant_id AND q.run_id=r.id AND (q.reconcile_after IS NULL OR q.reconcile_after<=clock_timestamp()))
 ORDER BY r.created_at,r.id LIMIT 1;
 IF candidate.id IS NULL THEN RETURN false;END IF;
 PERFORM 1 FROM photo.tenants tenant WHERE tenant.id=candidate.tenant_id
  AND tenant.status='active' FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO current_run FROM photo.runs r WHERE r.tenant_id=candidate.tenant_id
  AND r.id=candidate.id FOR UPDATE SKIP LOCKED;
 IF current_run.id IS NULL THEN RETURN false;END IF;
 PERFORM 1 FROM photo.tasks t WHERE t.tenant_id=current_run.tenant_id
  AND t.run_id=current_run.id ORDER BY t.id FOR UPDATE;
 PERFORM 1 FROM photo.reviews v WHERE v.tenant_id=current_run.tenant_id
  AND v.run_id=current_run.id ORDER BY v.id FOR SHARE;
 IF NOT photo.billing_local_selected_ready(current_run.tenant_id,current_run.id)
 THEN UPDATE photo.billing_operation_requests SET reconcile_after=clock_timestamp()+interval '30 seconds' WHERE tenant_id=current_run.tenant_id AND run_id=current_run.id AND state='accepted';RETURN false;END IF;
 IF current_run.revision>=9007199254740991
 THEN RAISE EXCEPTION 'REVISION_EXHAUSTED' USING ERRCODE='23514';END IF;
 INSERT INTO photo.tenant_event_cursors(tenant_id,last_cursor)
  VALUES(current_run.tenant_id,0) ON CONFLICT(tenant_id) DO NOTHING;
 UPDATE photo.tenant_event_cursors SET last_cursor=last_cursor+1
  WHERE tenant_id=current_run.tenant_id AND last_cursor<9007199254740991
  RETURNING last_cursor INTO cursor_value;
 IF NOT FOUND THEN RAISE EXCEPTION 'EVENT_CURSOR_EXHAUSTED' USING ERRCODE='23514';END IF;
 UPDATE photo.runs SET status='completed',revision=revision+1
  WHERE tenant_id=current_run.tenant_id AND id=current_run.id
   AND status='waiting_review' AND revision=current_run.revision;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_LOCAL_REVIEW_FINALIZATION_RACE' USING ERRCODE='23514';END IF;
 event_id:=photo.v30_uuid5(current_run.id,'billing:local:review:completed');
 INSERT INTO photo.run_events(tenant_id,cursor,run_id,principal_id,audience,type,payload)
 VALUES(current_run.tenant_id,cursor_value,current_run.id,current_run.created_by,
  'principal','v2.run.completed',jsonb_build_object('run_id',current_run.id,
   'status','completed','revision',current_run.revision+1));
 INSERT INTO photo.outbox(tenant_id,event_id,destination,routing_key,payload)
 VALUES(current_run.tenant_id,event_id,'photo.events.v1','v2.run.completed',
  jsonb_build_object('schema_version',1,'event_id',event_id,'type','v2.run.completed',
   'tenant_id',current_run.tenant_id,'run_id',current_run.id,'status','completed'));
 RETURN true;
END $$;
-- +goose StatementEnd
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION photo.billing_settle_next_operations() RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE b record;done boolean;native_progress boolean;
BEGIN
 native_progress:=photo.billing_finalize_local_selected();
 FOR b IN SELECT q.tenant_id,q.run_id FROM photo.billing_operation_requests q JOIN photo.runs r ON r.tenant_id=q.tenant_id AND r.id=q.run_id
 JOIN photo.billing_accounting_controls ctl ON ctl.tenant_id=q.tenant_id AND ctl.lifecycle='active'
 WHERE q.state='accepted' AND (q.reconcile_after IS NULL OR q.reconcile_after<=clock_timestamp()) AND r.status IN('completed','completed_with_errors','failed','cancelled') ORDER BY q.created_at,q.id LIMIT 16 LOOP
  PERFORM 1 FROM photo.tenants WHERE id=b.tenant_id AND status='active' FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE;END IF;
  done:=false;
  BEGIN done:=photo.billing_settle_operations(b.tenant_id,b.run_id);
  EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'BILLING_OPERATION_PROOF_UNAVAILABLE' THEN RAISE;END IF;END;
  IF done THEN RETURN true;END IF;
  UPDATE photo.billing_operation_requests SET reconcile_after=clock_timestamp()+interval '30 seconds' WHERE tenant_id=b.tenant_id AND run_id=b.run_id AND state='accepted';
 END LOOP;
 RETURN native_progress;
END $$;
-- +goose StatementEnd

